(async () => {
  await GameStudio.ready();
  const data = await GameStudio.getData();
  const $ = id => document.getElementById(id);
  $('marker').textContent = data.marker;
  let match = await GameStudio.getMatch();
  function render(m) {
    match = m;
    const s = m.state || { a: 0, b: 0 };
    $('score').textContent = m.players.a.name + ' ' + s.a + ' – ' + s.b + ' ' + m.players.b.name;
    $('secret').textContent = m.mine ? 'My secret: ' + m.mine.secret : 'No secret yet';
    const mine = m.turn === m.you && !m.over;
    $('move').disabled = !mine;
    $('status').textContent = m.over ? (m.over.winner === m.you ? 'You won' : 'You lost')
      : mine ? 'Your turn' : 'Waiting for ' + m.players[m.turn].name;
  }
  GameStudio.onMatchChange(render);
  render(match);
  $('move').onclick = async () => {
    const s = Object.assign({ a: 0, b: 0 }, match.state);
    s[match.you] += 1;
    const over = s[match.you] >= data.target ? { winner: match.you } : undefined;
    $('move').disabled = true;
    try { await GameStudio.makeMove({ point: match.you }, s, { mine: { secret: 'side-' + match.you }, over }); }
    catch (e) { $('status').textContent = 'Error: ' + e.message; }
  };
})();
